package com.nook.infrastructure.adapter.out.places;

import com.fasterxml.jackson.databind.*; import com.nook.application.port.out.PlacePhotoPort; import com.nook.application.port.out.PlacesProviderPort; import com.nook.domain.SocialEntities.CoffeeShop; import com.nook.exception.ApiException; import com.nook.repository.SocialRepository; import jakarta.transaction.Transactional; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Profile; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.*;

@Component @Profile("!demo-seed") public class GooglePlacesProvider implements PlacesProviderPort, PlacePhotoPort {
 private static final String FIELDS="places.id,places.displayName,places.formattedAddress,places.location,places.photos,places.rating,places.userRatingCount,places.regularOpeningHours,places.currentOpeningHours,places.priceLevel,places.websiteUri,places.nationalPhoneNumber,places.googleMapsUri,places.types,places.primaryType,places.primaryTypeDisplayName,places.editorialSummary";
 private final String key; private final SocialRepository repo; private final ObjectMapper json; private final RestClient http=placesClient(); private final Map<String,Entry> cache=new ConcurrentHashMap<>();
 public GooglePlacesProvider(@Value("${nook.google-places-api-key:}")String key,SocialRepository repo,ObjectMapper json){this.key=key;this.repo=repo;this.json=json;}
 @Override @Transactional public List<CoffeeShop> nearby(double lat,double lng,double radiusKm){configured();double radius=Math.max(.5,Math.min(radiusKm,50));String ck=Math.round(lat*500)+":"+Math.round(lng*500)+":"+Math.round(radius);Entry hit=cache.get(ck);if(hit!=null&&hit.at.plus(Duration.ofMinutes(3)).isAfter(Instant.now()))return hit.shops;try{Map<String,Object> body=Map.of("includedTypes",List.of("cafe","coffee_shop"),"maxResultCount",20,"rankPreference","DISTANCE","languageCode","es","regionCode","ES","locationRestriction",Map.of("circle",Map.of("center",Map.of("latitude",lat,"longitude",lng),"radius",radius*1000)));String raw=http.post().uri("/v1/places:searchNearby").contentType(MediaType.APPLICATION_JSON).header("X-Goog-Api-Key",key).header("X-Goog-FieldMask",FIELDS).body(body).retrieve().body(String.class);JsonNode places=json.readTree(raw==null?"{}":raw).path("places");List<CoffeeShop> out=new ArrayList<>();if(places.isArray())for(JsonNode p:places)if(isCoffeePrimaryType(p))out.add(upsert(p));cache.put(ck,new Entry(Instant.now(),List.copyOf(out)));return out;}catch(RestClientResponseException e){int status=e.getStatusCode().value();if(status==401||status==403)throw new ApiException(HttpStatus.BAD_GATEWAY,"PLACES_AUTH_ERROR","Google Places no está autorizado");if(status==429)throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"PLACES_QUOTA_EXCEEDED","Google Places ha alcanzado temporalmente su cuota");throw new ApiException(HttpStatus.BAD_GATEWAY,"PLACES_UPSTREAM_ERROR","Google Places ha devuelto un error");}catch(ResourceAccessException e){throw new ApiException(HttpStatus.GATEWAY_TIMEOUT,"PLACES_TIMEOUT","Google Places no ha respondido a tiempo");}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"PLACES_UNAVAILABLE","Google Places no está disponible en este momento");}}
 private CoffeeShop upsert(JsonNode p){String id=text(p,"id");CoffeeShop s=repo.shopByProviderId(id).orElseGet(CoffeeShop::new);s.provider="GOOGLE";s.providerId=id;s.active=true;s.name=p.path("displayName").path("text").asText("Cafetería");s.address=p.path("formattedAddress").asText("");s.latitude=p.path("location").path("latitude").asDouble();s.longitude=p.path("location").path("longitude").asDouble();s.rating=p.has("rating")?p.path("rating").asDouble():null;s.reviewCount=p.has("userRatingCount")?p.path("userRatingCount").asInt():null;s.openNow=p.path("currentOpeningHours").has("openNow")?p.path("currentOpeningHours").path("openNow").asBoolean():null;s.priceLevel=text(p,"priceLevel");s.website=text(p,"websiteUri");s.phone=text(p,"nationalPhoneNumber");s.mapsUrl=text(p,"googleMapsUri");s.types=join(p.path("types"),",");s.category=p.path("primaryTypeDisplayName").path("text").asText(null);s.description=shortText(p.path("editorialSummary").path("text").asText(null),155);s.openingHours=join(p.path("regularOpeningHours").path("weekdayDescriptions")," · ");JsonNode photos=p.path("photos");List<String> gallery=new ArrayList<>();if(photos.isArray())for(int i=0;i<Math.min(photos.size(),8);i++){String name=photos.get(i).path("name").asText();if(!name.isBlank())gallery.add(photoPath(name));}s.photoUrls=List.copyOf(gallery);s.photoUrl=gallery.isEmpty()?null:gallery.get(0);s.updatedAt=Instant.now();return repo.save(s);}
 @Override public PhotoAsset photo(String token){configured();try{String name=new String(Base64.getUrlDecoder().decode(token),StandardCharsets.UTF_8);if(!name.startsWith("places/")||!name.contains("/photos/"))throw new IllegalArgumentException();String descriptor=http.get().uri(u->u.path("/v1/"+name+"/media").queryParam("maxWidthPx",1200).queryParam("skipHttpRedirect",true).queryParam("key",key).build()).retrieve().body(String.class);String photoUri=json.readTree(descriptor==null?"{}":descriptor).path("photoUri").asText();if(photoUri.isBlank())throw new IllegalStateException();ResponseEntity<byte[]> r=RestClient.create().get().uri(photoUri).retrieve().toEntity(byte[].class);MediaType type=r.getHeaders().getContentType();return new PhotoAsset(r.getBody()==null?new byte[0]:r.getBody(),(type==null?MediaType.IMAGE_JPEG:type).toString());}catch(Exception e){throw new ApiException(HttpStatus.NOT_FOUND,"PLACE_PHOTO_NOT_FOUND","Foto no disponible");}}
 private static RestClient placesClient(){var requestFactory=new org.springframework.http.client.SimpleClientHttpRequestFactory();requestFactory.setConnectTimeout(Duration.ofSeconds(3));requestFactory.setReadTimeout(Duration.ofSeconds(8));return RestClient.builder().baseUrl("https://places.googleapis.com").requestFactory(requestFactory).build();} private static boolean isCoffeePrimaryType(JsonNode place){String primary=place.path("primaryType").asText("");return primary.equals("cafe")||primary.equals("coffee_shop");} private String photoPath(String name){return "/api/v1/coffee-shops/photos/"+Base64.getUrlEncoder().withoutPadding().encodeToString(name.getBytes(StandardCharsets.UTF_8));} private static String shortText(String value,int max){if(value==null||value.isBlank())return null;String clean=value.strip().replaceAll("\\s+"," ");if(clean.length()<=max)return clean;int cut=clean.lastIndexOf(' ',max-1);return clean.substring(0,cut>80?cut:max-1).strip()+"…";} private void configured(){if(key==null||key.isBlank())throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"PLACES_NOT_CONFIGURED","Google Places todavía no está configurado");} private static String text(JsonNode n,String f){return n.hasNonNull(f)?n.path(f).asText():null;} private static String join(JsonNode n,String sep){if(!n.isArray())return null;List<String>x=new ArrayList<>();n.forEach(v->x.add(v.asText()));return String.join(sep,x);} private record Entry(Instant at,List<CoffeeShop> shops){}
}
